def gatekeeper(allowed, visitors):
    if not allowed:
        print("No one is allowed in yet.")
        return
    for visitor in visitors:
        if visitor in allowed:
            print(f"{visitor}: welcome in.")
        else:
            print(f"{visitor}: not on the list.")
    if "Ghost" not in allowed:
        print("Ghost is not an approved name.")

gatekeeper(["Nyx", "Bram"], ["Nyx", "Fen", "Bram"])
